 <html lang="en">
   <head>
     <meta charset="utf-8">
     <meta name="viewport" content="width=device-width, initial-scale=1">
     <title>Product card</title>
     <link rel="stylesheet" href="product-card.css">
     <style>
       body {
         margin: 0;
