    "addToCart": "أضف إلى السلة",
    "inStock": "متوفر",
    "onlyLeft": "لم يتبقَّ سوى {count}",
    "outOfStock": "غير متوفر"
  },
  "problems": [
    "product-card.js does not set lang=\"ar\" or dir=\"rtl\". Unless an ancestor supplies them, Arabic layout remains LTR and product-card.css positions the wishlist on the wrong side. Its logical CSS properties already support RTL when direction is set.",
    "formatPrice() hardcodes \"$\" and uses toFixed(2), so currency, digits, separators, and currency placement are not localized. Use Intl.NumberFormat with the Arabic locale and the actual currency.",
    "stockLabel() inserts product.stock without locale-aware number formatting.",
    "product.name and product.description come directly from product data; translating these messages does not translate that content. Mixed-direction names also lack explicit bidirectional isolation."
  ]
}
